// Injected test helper: polls a command file and performs real AppKit drag
// destination calls on the app's WKWebViews, or runs JS in them.
#import <AppKit/AppKit.h>
#import <WebKit/WebKit.h>

static NSString *gDir;
static void logline(NSString *s) {
    NSString *p = [gDir stringByAppendingPathComponent:@"out.log"];
    NSFileHandle *h = [NSFileHandle fileHandleForWritingAtPath:p];
    if (!h) { [[NSFileManager defaultManager] createFileAtPath:p contents:nil attributes:nil]; h = [NSFileHandle fileHandleForWritingAtPath:p]; }
    [h seekToEndOfFile];
    [h writeData:[[s stringByAppendingString:@"\n"] dataUsingEncoding:NSUTF8StringEncoding]];
    [h closeFile];
}

@interface FakeDrag : NSObject <NSDraggingInfo>
@property (strong) NSPasteboard *pb;
@property (weak) NSWindow *win;
@property NSPoint loc;
@end
@implementation FakeDrag
@synthesize draggingFormation, animatesToDestination, numberOfValidItemsForDrop, springLoadingHighlight;
- (NSWindow *)draggingDestinationWindow { return self.win; }
- (NSDragOperation)draggingSourceOperationMask { return NSDragOperationCopy | NSDragOperationLink | NSDragOperationGeneric | NSDragOperationMove; }
- (NSPoint)draggingLocation { return self.loc; }
- (NSPoint)draggedImageLocation { return self.loc; }
- (NSImage *)draggedImage { return nil; }
- (NSPasteboard *)draggingPasteboard { return self.pb; }
- (id)draggingSource { return nil; }
- (NSInteger)draggingSequenceNumber { return 4242; }
- (void)slideDraggedImageTo:(NSPoint)p {}
- (NSArray<NSString *> *)namesOfPromisedFilesDroppedAtDestination:(NSURL *)u { return nil; }
- (void)enumerateDraggingItemsWithOptions:(NSDraggingItemEnumerationOptions)o forView:(NSView *)v classes:(NSArray<Class> *)c searchOptions:(NSDictionary *)s usingBlock:(void (^)(NSDraggingItem *, NSInteger, BOOL *))b {}
- (void)resetSpringLoading {}
@end

static void collect(NSView *v, NSMutableArray *out) {
    if ([v isKindOfClass:[WKWebView class]]) [out addObject:v];
    for (NSView *s in v.subviews) collect(s, out);
}
static NSArray<WKWebView *> *webviews(void) {
    NSMutableArray *out = [NSMutableArray array];
    for (NSWindow *w in [NSApp windows]) if (w.contentView) collect(w.contentView, out);
    return out;
}
static WKWebView *find(NSString *needle) {
    for (WKWebView *wv in webviews())
        if ([wv.URL.absoluteString containsString:needle] && wv.window.isVisible && !wv.isHiddenOrHasHiddenAncestor) return wv;
    return nil;
}

static void doDrop(NSString *needle, NSString *path, double fx, double fy) {
    WKWebView *wv = find(needle);
    if (!wv) { logline([NSString stringWithFormat:@"drop: no visible web view matching %@", needle]); return; }
    NSRect b = wv.bounds;
    double y = wv.isFlipped ? fy * b.size.height : (1 - fy) * b.size.height;
    NSPoint winPt = [wv convertPoint:NSMakePoint(fx * b.size.width, y) toView:nil];
    NSPasteboard *pb = [NSPasteboard pasteboardWithUniqueName];
    [pb clearContents];
    [pb writeObjects:@[[NSURL fileURLWithPath:path]]];
    FakeDrag *d = [FakeDrag new];
    d.pb = pb; d.win = wv.window; d.loc = winPt;
    logline([NSString stringWithFormat:@"drop: %@ at %.2f,%.2f of %@ (%.0fx%.0f)", path, fx, fy, wv.URL.lastPathComponent, b.size.width, b.size.height]);
    NSDragOperation op = [wv draggingEntered:d];
    logline([NSString stringWithFormat:@"drop: entered -> %lu", (unsigned long)op]);
    __block int n = 0;
    __block void (^step)(void);
    step = ^{
        if (n++ < 6) {
            NSDragOperation u = [wv draggingUpdated:d];
            logline([NSString stringWithFormat:@"drop: updated -> %lu", (unsigned long)u]);
            dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 200 * NSEC_PER_MSEC), dispatch_get_main_queue(), step);
            return;
        }
        BOOL prep = [wv prepareForDragOperation:d];
        BOOL perf = [wv performDragOperation:d];
        [wv concludeDragOperation:d];
        logline([NSString stringWithFormat:@"drop: prepare=%d perform=%d", prep, perf]);
        step = nil;
    };
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 200 * NSEC_PER_MSEC), dispatch_get_main_queue(), step);
}

static void doJs(NSString *needle, NSString *js) {
    // Match by URL, visible or not, so a page that navigated away is still found.
    WKWebView *target = nil;
    for (WKWebView *wv in webviews()) if ([needle isEqualToString:@"*"] || [wv.URL.absoluteString containsString:needle]) { target = wv; break; }
    if (!target) { logline([NSString stringWithFormat:@"js: no web view matching %@", needle]); return; }
    [target evaluateJavaScript:js completionHandler:^(id r, NSError *e) {
        logline([NSString stringWithFormat:@"js: %@", e ? e.localizedDescription : [r description]]);
    }];
}

static void poll(void) {
    NSString *cmdPath = [gDir stringByAppendingPathComponent:@"cmd.txt"];
    NSString *cmd = [NSString stringWithContentsOfFile:cmdPath encoding:NSUTF8StringEncoding error:nil];
    if (cmd.length) {
        [[NSFileManager defaultManager] removeItemAtPath:cmdPath error:nil];
        for (NSString *line in [cmd componentsSeparatedByString:@"\n"]) {
            NSArray *p = [line componentsSeparatedByString:@"\t"];
            if ([p[0] isEqualToString:@"list"]) {
                for (WKWebView *wv in webviews())
                    logline([NSString stringWithFormat:@"list: %@ visible=%d frame=%@", wv.URL.absoluteString, wv.window.isVisible && !wv.isHiddenOrHasHiddenAncestor, NSStringFromRect([wv convertRect:wv.bounds toView:nil])]);
            } else if ([p[0] isEqualToString:@"drop"] && p.count >= 5) {
                doDrop(p[1], p[2], [p[3] doubleValue], [p[4] doubleValue]);
            } else if ([p[0] isEqualToString:@"js"] && p.count >= 3) {
                doJs(p[1], p[2]);
            }
        }
    }
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 300 * NSEC_PER_MSEC), dispatch_get_main_queue(), ^{ poll(); });
}

__attribute__((constructor)) static void init(void) {
    const char *dir = getenv("JP_DROPPER_DIR");
    if (!dir) return;
    gDir = [NSString stringWithUTF8String:dir];
    dispatch_async(dispatch_get_main_queue(), ^{ poll(); });
}
